{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic does not specify a `kms_key_name`, which means it will use Google-managed encryption keys by default. Using Customer Supplied Encryption Keys (CSEK) provides greater control over data encryption and access."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n  kms_key_name = \"projects/my-project/locations/global/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to specify a Customer Supplied Encryption Key (CSEK) for the PubSub topic, ensuring better control over encryption."
}
